//! Loading and running apps the server hands over.
//!
//! The contract is deliberately at the JS boundary rather than in wasm imports:
//!
//! ```text
//! init(wasm_url_or_response)   instantiate (generated by wasm-bindgen)
//! mount(el, host) -> id        render into `el`
//! unmount(id)                  tear down
//! ```
//!
//! Three consequences worth knowing:
//!
//! * **One instance, many windows.** A loaded module is cached by `id@version`, and
//!   `mount` is called once per window. The app's reactive root is created per call,
//!   so two Calculator windows share code but not state.
//! * **The host object is data, not imports.** `mount` receives an object of
//!   functions; nothing links at instantiation time. That is what keeps the door open
//!   to running an app behind a sandboxed boundary later without rewriting the ABI.
//! * **Each app is its own reactive world.** A separate wasm instance has its own
//!   memory and statics, so an app cannot see the shell's signals. Cross-app effects
//!   go through the host or the server.
//!
//! Trust: a module is imported from our own origin, so it runs with full
//! same-origin privileges, exactly like the shell's own code. Installing an app is
//! trusting it. See the README.

use std::cell::RefCell;
use std::collections::HashMap;

use js_sys::{Function, Object, Reflect, Uint8Array};
use sha2::{Digest, Sha256};
use shared::{APP_ABI, AppManifest};
use wasm_bindgen::{JsCast, JsValue, closure::Closure};
use wasm_bindgen_futures::JsFuture;

use crate::state::Desktop;

/// Refuse an app bundle larger than this before downloading it.
pub const MAX_APP_BYTES: u64 = 16 * 1024 * 1024;

thread_local! {
    /// Loaded module namespaces, keyed by `id@version`.
    static MODULES: RefCell<HashMap<String, JsValue>> = RefCell::new(HashMap::new());
}

/// Progress of one served app inside one window.
#[derive(Clone, PartialEq)]
pub enum Load {
    Loading,
    Ready,
    Failed(String),
}

/// A mounted app instance, enough to tear it down again.
#[derive(Clone, PartialEq)]
pub struct Mounted {
    module_key: String,
    instance: u32,
}

/// Fetch, verify and mount an app. `container` is where it renders.
pub async fn mount(
    manifest: &AppManifest,
    window_id: u32,
    container: web_sys::HtmlElement,
    desktop: Desktop,
) -> Result<Mounted, String> {
    let served = manifest
        .served()
        .ok_or_else(|| "not a served app".to_owned())?;

    if served.abi != APP_ABI {
        return Err(format!(
            "needs shell ABI {} but this shell speaks {APP_ABI}",
            served.abi
        ));
    }
    if served.size > MAX_APP_BYTES {
        return Err(format!(
            "bundle is {} bytes; the limit is {MAX_APP_BYTES}",
            served.size
        ));
    }

    let base = manifest
        .served_base_url()
        .ok_or_else(|| "no bundle URL".to_owned())?;
    let module_key = format!("{}@{}", manifest.id, served.version);

    let module = module_for(
        &module_key,
        &format!("{base}{}", served.entry),
        &format!("{base}{}", served.wasm),
        &served.sha256,
    )
    .await?;

    let mount = function(&module, "mount")?;
    let host = build_host(desktop, manifest, window_id);
    let instance = mount
        .call2(&JsValue::NULL, &container, &host)
        .map_err(|err| describe("mount", &err))?
        .as_f64()
        .ok_or_else(|| "mount did not return an instance id".to_owned())?;

    Ok(Mounted {
        module_key,
        instance: instance as u32,
    })
}

/// Tear down an instance. Dropping the app's reactive owner happens inside the app,
/// so a closed window leaves nothing behind.
pub fn unmount(mounted: &Mounted) {
    let module = MODULES.with(|modules| modules.borrow().get(&mounted.module_key).cloned());
    if let Some(module) = module
        && let Ok(unmount) = function(&module, "unmount")
    {
        let _ = unmount.call1(
            &JsValue::NULL,
            &JsValue::from_f64(f64::from(mounted.instance)),
        );
    }
}

/// Get a loaded module, or load it: import the entry, verify the wasm, instantiate.
async fn module_for(
    key: &str,
    entry_url: &str,
    wasm_url: &str,
    expected_sha: &str,
) -> Result<JsValue, String> {
    if let Some(module) = MODULES.with(|modules| modules.borrow().get(key).cloned()) {
        return Ok(module);
    }

    // A dynamic import needs a real `import()`; there is no binding for the syntax,
    // so build one from source.
    let import = Function::new_with_args("url", "return import(url)");
    let importing = import.call1(&JsValue::NULL, &JsValue::from_str(entry_url));
    let module = JsFuture::from(promise(importing, "import")?)
        .await
        .map_err(|err| describe("import", &err))?;

    // Fetch the wasm, check its digest, and instantiate *those* bytes: verifying a
    // response that is then re-fetched would prove nothing.
    let bytes = fetch(wasm_url).await?;
    let digest = hex(&Sha256::digest(&bytes));
    if digest != expected_sha.to_ascii_lowercase() {
        return Err(format!(
            "checksum mismatch for {key}: the manifest says {}, the bundle hashes to {digest}",
            &expected_sha[..expected_sha.len().min(12)]
        ));
    }

    let init = function(&module, "default")?;
    let buffer = Uint8Array::from(&bytes[..]);
    let starting = init.call1(&JsValue::NULL, buffer.as_ref());
    JsFuture::from(promise(starting, "init")?)
        .await
        .map_err(|err| describe("init", &err))?;

    MODULES.with(|modules| modules.borrow_mut().insert(key.to_owned(), module.clone()));
    Ok(module)
}

/// Download a bundle file. `gloo-net` decodes the body for us, and the bytes are
/// what gets hashed and then handed to `init`.
async fn fetch(url: &str) -> Result<Vec<u8>, String> {
    let response = gloo_net::http::Request::get(url)
        .send()
        .await
        .map_err(|err| format!("fetching {url} failed: {err}"))?;

    if !response.ok() {
        return Err(format!("{url} returned HTTP {}", response.status()));
    }
    response
        .binary()
        .await
        .map_err(|err| format!("reading {url} failed: {err}"))
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// A JS call that should have returned a promise, as the typed `Promise` that
/// `JsFuture` wants.
fn promise(value: Result<JsValue, JsValue>, what: &str) -> Result<js_sys::Promise, String> {
    value
        .map_err(|err| describe(what, &err))?
        .dyn_into::<js_sys::Promise>()
        .map_err(|_| format!("{what} did not return a promise"))
}

fn function(module: &JsValue, name: &str) -> Result<Function, String> {
    Reflect::get(module, &JsValue::from_str(name))
        .ok()
        .and_then(|value| value.dyn_into::<Function>().ok())
        .ok_or_else(|| format!("the app bundle does not export `{name}`"))
}

/// The object an app receives: plain data plus a few calls back into the shell.
///
/// Kept small on purpose. Anything an app can reach over HTTP (the file API, for
/// instance) is deliberately *not* repeated here.
fn build_host(desktop: Desktop, manifest: &AppManifest, window_id: u32) -> JsValue {
    let app_id = manifest.id.clone();
    let host = Object::new();
    let _ = Reflect::set(&host, &"appId".into(), &app_id.clone().into());
    let _ = Reflect::set(&host, &"windowId".into(), &f64::from(window_id).into());

    let window = desktop.window(window_id);
    let size = Object::new();
    let _ = Reflect::set(&size, &"width".into(), &window.map_or(0.0, |w| w.w).into());
    let _ = Reflect::set(&size, &"height".into(), &window.map_or(0.0, |w| w.h).into());
    let _ = Reflect::set(&host, &"size".into(), &size);

    let theme = Object::new();
    // The app's own accent, so its UI can match the title bar and taskbar button the
    // shell draws for it; the rest of the palette comes from the shell.
    let _ = Reflect::set(&theme, &"accent".into(), &manifest.accent.clone().into());
    for (key, var) in [
        ("text", "--text"),
        ("muted", "--muted"),
        ("panel", "--panel-solid"),
        ("stroke", "--stroke"),
    ] {
        let _ = Reflect::set(&theme, &key.into(), &css_variable(var).into());
    }
    let _ = Reflect::set(&host, &"theme".into(), &theme);

    // Closures are turned into JS values, so the host object owns them and they are
    // collected with it. No Rust-side handle to keep alive — but they must own what
    // they capture, since a `Closure` is `'static`.
    let log = Closure::<dyn FnMut(JsValue)>::new(move |message: JsValue| {
        let text = message.as_string().unwrap_or_default();
        web_sys::console::log_1(&format!("[{app_id}] {text}").into());
    });
    let _ = Reflect::set(&host, &"log".into(), &log.into_js_value());

    let open = Closure::<dyn FnMut(JsValue)>::new(move |slug: JsValue| {
        if let Some(slug) = slug.as_string()
            && let Err(err) = desktop.open_slug(&slug)
        {
            web_sys::console::warn_1(&err.into());
        }
    });
    let _ = Reflect::set(&host, &"openApp".into(), &open.into_js_value());

    let close = Closure::<dyn FnMut()>::new(move || desktop.close(window_id));
    let _ = Reflect::set(&host, &"close".into(), &close.into_js_value());

    host.into()
}

/// A CSS custom property from the document root, so an app can match the desktop.
fn css_variable(name: &str) -> String {
    let Some(document) = web_sys::window().and_then(|w| w.document()) else {
        return String::new();
    };
    let Some(root) = document.document_element() else {
        return String::new();
    };
    web_sys::window()
        .and_then(|w| w.get_computed_style(&root).ok().flatten())
        .and_then(|style| style.get_property_value(name).ok())
        .map(|value| value.trim().to_owned())
        .unwrap_or_default()
}

fn describe(what: &str, err: &JsValue) -> String {
    let text = err
        .as_string()
        .or_else(|| {
            Reflect::get(err, &"message".into())
                .ok()
                .and_then(|m| m.as_string())
        })
        .unwrap_or_else(|| format!("{err:?}"));
    format!("{what} failed: {text}")
}
